 function reviewKeywords(l){
  const stop=new Set(["the","and","with","from","this","that","your","into","using","use","used","work","build","test","lesson","robot","robotics","real","actual","create","make","good","should","could","would","will","must","need","what","when","where","why","how","their","they","them","then","also","more","less","each","one","two","three","four","page","step","steps","result","evidence","check","complete","completed","about","after","before","over","under","very","such","have","has","had","for","are","was","were","been","being","its","our","out","all","any","can","not","but","you","is","of","in","on","to","a","an","or","as","by","at","it"]);
  const source=[l.title||"",l.body||"",l.task||""].join(" ").toLowerCase();
  const words=source.match(/[a-z][a-z0-9+#.-]{2,}/g)||[];
  return [...new Set(words.filter(w=>w.length>2&&!stop.has(w)))].slice(0,8);
 }
 function matchedReviewKeywords(l,evidence){
  const words=new Set((evidence.toLowerCase().match(/[a-z][a-z0-9+#.-]{2,}/g)||[]));
  return reviewKeywords(l).filter(w=>words.has(w));
 }
 function codeLessonFor(l){
  const t=(l.title+" "+l.body+" "+l.task).toLowerCase();
  const make=(name,task,code,lines,integration)=>({name,task,code,lines,integration});
  if(/project structure|android studio|gradle|packages|imports/.test(t))return make("Java project structure","Read the class, package, imports, and entry point. Change the message and compile.",'package org.firstinspires.ftc.teamcode;\n\npublic class Main {\n    public static void main(String[] args) {\n        System.out.println("Rangers Java project ready");\n    }\n}',[["package org.firstinspires.ftc.teamcode;","Declares the namespace for this class. In an FTC project, the package path must match the folder structure."],["public class Main {","Declares a class named Main. Java source files normally use the same name as their public class."],["public static void main(String[] args) {","This is the standard Java program entry point used by this online compiler. FTC OpModes use an SDK lifecycle instead."],["System.out.println(...);","Writes a line to the console so you can verify the program ran."]],"FTC classes belong in the TeamCode module and use the FTC SDK; this standard Java entry point is only for the browser compiler.");
  if(/syntax|statements|blocks|semicolons/.test(t))return make("Java statements and blocks","Fix the deliberately incomplete statement, then change the two values and run again.",'public class Main {\n    public static void main(String[] args) {\n        double speed = 0.65;\n        boolean enabled = true;\n        if (enabled) {\n            System.out.println("Command: " + speed);\n        }\n    }\n}',[["double speed = 0.65;","Declares a decimal variable. The semicolon ends this Java statement."],["boolean enabled = true;","Stores a true/false value that controls whether the block runs."],["if (enabled) {","Begins a conditional block. Curly braces group the statements that belong to it."],["System.out.println(...);","Prints text plus the value of speed. The plus operator joins strings with other values."]],"Use the same Java syntax in FTC classes, but put robot behavior in the appropriate OpMode or subsystem method.");
  if(/variable|data type|configuration value|constant/.test(t))return make("Typed robot configuration","Change the constants, then print a summary. Try assigning text to a numeric variable and inspect the compiler error.",'public class Main {\n    static final double MAX_DRIVE = 0.75;\n    static final int AUTO_DELAY_MS = 250;\n    static final String INTAKE_NAME = "intake_motor";\n    public static void main(String[] args) {\n        boolean fieldCentric = false;\n        System.out.println(MAX_DRIVE);\n        System.out.println(AUTO_DELAY_MS);\n        System.out.println(INTAKE_NAME + " / field-centric: " + fieldCentric);\n    }\n}',[["static final double MAX_DRIVE = 0.75;","Creates a class-level constant. static means it belongs to the class; final prevents reassignment; double stores decimals."],["static final int AUTO_DELAY_MS = 250;","Stores a whole-number duration. The MS suffix in the name documents the unit."],["static final String INTAKE_NAME = ...;","Stores the exact hardware configuration name as text."],["boolean fieldCentric = false;","Creates a true/false setting that can be changed while the program runs."]],"Keep hardware names and tuning values centralized. Confirm every hardware name against the Robot Configuration.");
  if(/operator|expression|if and else|conditional/.test(t))return make("Decision logic and operators","Change the inputs and predict which branch runs before compiling.",'public class Main {\n    static String chooseMode(double right, double left) {\n        if (right > 0.05 && right >= left) {\n            return "FORWARD";\n        } else if (left > 0.05) {\n            return "REVERSE";\n        }\n        return "STOP";\n    }\n    public static void main(String[] args) {\n        System.out.println(chooseMode(0.8, 0.2));\n        System.out.println(chooseMode(0.0, 0.7));\n        System.out.println(chooseMode(0.0, 0.0));\n    }\n}',[["right > 0.05","Compares a trigger value with a small dead zone. The result is true or false."],["&& right >= left","&& means both conditions must be true. This gives the right trigger priority when both are pressed."],["else if (left > 0.05)","Checks the reverse condition only when the first condition was false."],["return \"STOP\";","Returns a safe neutral decision when neither trigger is active."]],"In TeleOp, read the gamepad values each loop and use the returned decision to select motor output.");
  if(/switch|enum|state machine|state transition/.test(t))return make("Enums and state transitions","Add a new state or transition, then run the sequence and observe the printed states.",'public class Main {\n    enum IntakeState { IDLE, INTAKING, TRANSFER }\n    static IntakeState update(IntakeState state, boolean objectSeen, boolean cancel) {\n        if (cancel) return IntakeState.IDLE;\n        switch (state) {\n            case IDLE: return IntakeState.INTAKING;\n            case INTAKING: return objectSeen ? IntakeState.TRANSFER : IntakeState.INTAKING;\n            case TRANSFER: return IntakeState.IDLE;\n            default: return IntakeState.IDLE;\n        }\n    }\n    public static void main(String[] args) {\n        IntakeState state = IntakeState.IDLE;\n        state = update(state, false, false); System.out.println(state);\n        state = update(state, true, false); System.out.println(state);\n    }\n}',[["enum IntakeState {...}","Defines a fixed set of named states. This is clearer and safer than unexplained integer values."],["if (cancel) return ...;","Gives cancel priority and exits the method immediately."],["switch (state)","Selects a branch based on the current state."],["case INTAKING:","Runs this branch only while the mechanism is in the INTAKING state."],["objectSeen ? TRANSFER : INTAKING","The conditional operator chooses TRANSFER when objectSeen is true; otherwise it keeps INTAKING."]],"Run state transitions inside a non-blocking OpMode loop. Define what happens on timeout, cancel, and sensor failure.");
  if(/loop|iteration|for each/.test(t))return make("Loops and iteration","Change the array values and loop bounds. Notice how each item is processed once.",'public class Main {\n    public static void main(String[] args) {\n        double[] powers = {0.2, 0.4, 0.6, 0.8};\n        for (int i = 0; i < powers.length; i++) {\n            double clipped = Math.min(1.0, Math.max(-1.0, powers[i]));\n            System.out.println("Motor " + i + ": " + clipped);\n        }\n    }\n}',[["double[] powers = {...};","Creates an array holding several decimal motor commands."],["int i = 0;","Starts the loop counter at the first array index."],["i < powers.length;","Keeps looping while the index is smaller than the number of array elements."],["i++","Increases the index by one after each pass."],["powers[i]","Reads the array value at the current index."]],"A loop inside an FTC OpMode should stay responsive. Avoid long blocking work or unbounded loops that prevent stop handling.");
  if(/method|parameter|return value|scope/.test(t))return make("Methods, parameters, and return values","Change the method inputs and test values. Add one extra test for a negative request.",'public class Main {\n    static double clipPower(double requested, double scale) {\n        double scaled = requested * scale;\n        return Math.max(-1.0, Math.min(1.0, scaled));\n    }\n    public static void main(String[] args) {\n        System.out.println(clipPower(0.8, 0.5));\n        System.out.println(clipPower(-1.5, 1.0));\n    }\n}',[["static double clipPower(...)","Declares a reusable method that returns a double. Its parameters are the inputs provided by the caller."],["double scaled = requested * scale;","Creates a local variable. It exists only inside this method."],["Math.min(1.0, scaled)","Caps the value at the positive limit."],["Math.max(-1.0, ...)","Applies the negative limit too, keeping the result between -1 and 1."],["return ...;","Sends the calculated value back to the caller."]],"Pure helper methods are easy to test without robot hardware. Call them from your OpMode or subsystem.");
  if(/class|object|constructor|encapsulation|access modifier|subsystem/.test(t))return make("A reusable robot subsystem class","Create a second Intake object with a different name, then call each method.",'class Intake {\n    private double power;\n    Intake() {\n        power = 0.0;\n    }\n    public void setPower(double requested) {\n        power = Math.max(-1.0, Math.min(1.0, requested));\n    }\n    public double getPower() {\n        return power;\n    }\n}\npublic class Main {\n    public static void main(String[] args) {\n        Intake intake = new Intake();\n        intake.setPower(0.65);\n        System.out.println(intake.getPower());\n    }\n}',[["class Intake {","Defines a new type that groups intake data and behavior."],["private double power;","Stores the object's current power. private prevents unrelated classes from changing it directly."],["Intake()","This constructor runs when new Intake() creates an object."],["public void setPower(double requested)","Defines a method that accepts a requested value and does not return a result (void)."],["public double getPower()","Returns the stored value so other code can read it."],["new Intake()","Creates a separate object with its own power field."]],"For FTC, inject or pass the hardware map into subsystem initialization and keep hardware fields private.");
  if(/array|list|collection/.test(t))return make("Arrays and lists of robot devices","Add a fifth value or change the loop. Explain why the index starts at zero.",'import java.util.ArrayList;\nimport java.util.List;\npublic class Main {\n    public static void main(String[] args) {\n        List<String> devices = new ArrayList<>();\n        devices.add("front_left");\n        devices.add("front_right");\n        devices.add("back_left");\n        devices.add("back_right");\n        for (String name : devices) {\n            System.out.println("Configured: " + name);\n        }\n    }\n}',[["List<String> devices","Declares a list that stores String values. The type inside angle brackets is the element type."],["new ArrayList<>()","Creates the actual resizable list object."],["devices.add(...)","Appends one hardware name to the list."],["for (String name : devices)","Enhanced for loop: visits each item and stores the current item in name."],["devices.size()","Returns how many items are currently in the list."]],"Use typed collections to organize related devices or configuration data. Verify each configured name before hardware lookup.");
  if(/compiler error|debugging|exception|null check|defensive/.test(t))return make("Debugging and defensive checks","Uncomment the invalid line to see a compiler error, then fix it. Change the input to null to test the guard.",'public class Main {\n    static String deviceLabel(String configuredName) {\n        if (configuredName == null || configuredName.isEmpty()) {\n            return "DEVICE NAME MISSING";\n        }\n        return "Mapped device: " + configuredName;\n    }\n    public static void main(String[] args) {\n        System.out.println(deviceLabel("intake_motor"));\n        System.out.println(deviceLabel(null));\n    }\n}',[["configuredName == null","Checks that a reference actually points to an object before calling methods on it."],["|| configuredName.isEmpty()","|| means OR. The second check runs only if the first is false, so null is not dereferenced."],["return \"DEVICE NAME MISSING\";","Returns a clear diagnostic instead of causing a NullPointerException."],["return \"Mapped device: \" + configuredName;","Returns a useful message when a valid name was supplied."]],"Handle expected configuration problems with clear telemetry. Do not catch and silently ignore programming errors.");
  if(/telemetry|logging|diagnostic/.test(t))return make("Telemetry and diagnostics","Change the sample state and reading. Identify which values would help diagnose a robot issue.",'public class Main {\n    public static void main(String[] args) {\n        String state = "INTAKING";\n        double distanceCm = 8.4;\n        double motorPower = 0.65;\n        System.out.println("State: " + state);\n        System.out.println("Distance (cm): " + distanceCm);\n        System.out.println("Motor power: " + motorPower);\n    }\n}',[["String state = ...;","Stores a named mechanism state that is easy to read in diagnostics."],["double distanceCm = 8.4;","Stores a sensor reading and includes the unit in the variable name."],["System.out.println(...)","The browser-console equivalent of a diagnostic line. In FTC, use telemetry.addData(...) and telemetry.update()."]],"In an FTC OpMode, report a small set of useful values with telemetry.addData and telemetry.update; avoid flooding the driver station.");
  if(/opmode|linearopmode|iterative|lifecycle|hardwaremap|robot configuration/.test(t))return make("FTC lifecycle and hardware-map simulation","Compile and run this standard Java model of FTC initialization and the active loop. Then read the FTC integration note to see the real SDK calls.",'import java.util.HashMap;\nimport java.util.Map;\npublic class Main {\n    public static void main(String[] args) {\n        Map<String, String> configuredDevices = new HashMap<>();\n        configuredDevices.put("intake_motor", "DcMotor on port 0");\n        String motor = configuredDevices.get("intake_motor");\n        if (motor == null) {\n            System.out.println("Configuration error: intake_motor missing");\n            return;\n        }\n        System.out.println("INIT: " + motor);\n        boolean started = true;\n        if (started) System.out.println("RUNNING: active loop would begin");\n        System.out.println("STOP: set motor output to zero");\n    }\n}',[["Map<String, String> configuredDevices","Creates a lookup table that connects a configured hardware name to a simulated device description."],["new HashMap<>()","Creates the map that stores the name-to-device entries."],["configuredDevices.put(...)","Adds the exact Robot Configuration name. The spelling must match the name used by the robot code."],["configuredDevices.get(\"intake_motor\")","Looks up the device by name, similar in purpose to FTC hardwareMap.get(...)."],["if (motor == null)","Checks whether the lookup failed before trying to use the device."],["boolean started = true;","Models the point where the driver starts the OpMode."],["System.out.println(\"STOP...\")","Models the neutral-output step that should happen when the OpMode ends."]],"In real FTC code, map the device with hardwareMap.get(DcMotor.class, \"intake_motor\") during OpMode initialization. LinearOpMode uses waitForStart() and while (opModeIsActive()); iterative OpModes use init(), start(), loop(), and stop(). Those SDK classes must be built in the FTC project.");
  if(/motor|run mode|zero.power|encoder|ticks|distance move|turn target/.test(t))return make("Motor control and encoder math","Change the requested distance and hardware constants to see how target ticks change.",'public class Main {\n    static int targetTicks(double inches, double wheelDiameter, int ticksPerRev, double gearRatio) {\n        double wheelCircumference = Math.PI * wheelDiameter;\n        double motorRevs = inches / wheelCircumference * gearRatio;\n        return (int) Math.round(motorRevs * ticksPerRev);\n    }\n    public static void main(String[] args) {\n        System.out.println(targetTicks(24.0, 3.78, 537, 1.0));\n    }\n}',[["Math.PI * wheelDiameter","Calculates wheel circumference, the distance traveled per wheel revolution."],["inches / wheelCircumference","Converts requested travel distance into wheel revolutions."],["* gearRatio","Accounts for the relationship between motor revolutions and wheel revolutions. Define the ratio convention carefully."],["* ticksPerRev","Converts motor revolutions into encoder counts."],["Math.round(...)","Rounds the calculated target to a whole encoder tick."]],"Use measured wheel diameter and the motor's documented encoder counts. FTC RUN_TO_POSITION also needs target, mode, power, and non-blocking completion checks.");
  if(/servo|claw|end effector/.test(t))return make("Servo position control","Change the positions and test open, hold, and closed output values.",'public class Main {\n    static double clawPosition(String command) {\n        switch (command) {\n            case "OPEN": return 0.78;\n            case "CLOSE": return 0.22;\n            default: return 0.50;\n        }\n    }\n    public static void main(String[] args) {\n        System.out.println(clawPosition("OPEN"));\n        System.out.println(clawPosition("CLOSE"));\n        System.out.println(clawPosition("HOLD"));\n    }\n}',[["static double clawPosition(String command)","Defines a method that receives a named command and returns a servo position."],["switch (command)","Chooses a result based on the text command."],["case \"OPEN\": return 0.78;","Returns the example open position. This value must be calibrated to the real mechanism."],["default: return 0.50;","Provides a fallback when the command is not OPEN or CLOSE."],["System.out.println(...)","Prints each result so you can inspect the selected position."]],"FTC standard Servo uses setPosition from 0.0 to 1.0. Calibrate mechanism endpoints and avoid forcing the linkage.");
  if(/gamepad|trigger|button|toggle|deadzones|deadzone|joystick|input/.test(t))return make("Gamepad input processing","Change the stick values and deadzone. Observe how small stick drift is ignored.",'public class Main {\n    static double applyDeadzone(double input, double deadzone) {\n        if (Math.abs(input) < deadzone) return 0.0;\n        return Math.copySign((Math.abs(input) - deadzone) / (1.0 - deadzone), input);\n    }\n    public static void main(String[] args) {\n        System.out.println(applyDeadzone(0.03, 0.08));\n        System.out.println(applyDeadzone(0.50, 0.08));\n        System.out.println(applyDeadzone(-0.50, 0.08));\n    }\n}',[["Math.abs(input)","Gets the input magnitude without changing its sign."],["if (... < deadzone)","Checks whether the stick movement is small enough to treat as neutral."],["return 0.0;","Removes tiny drift around the center."],["(abs - deadzone) / (1 - deadzone)","Rescales the remaining range so full stick travel still reaches 1.0."],["Math.copySign(..., input)","Restores the original positive or negative direction."]],"Apply this helper to gamepad stick values inside the OpMode loop. Test the response with the robot safely disabled or supported.");
  if(/mecanum|field.centric|tank drive|arcade drive|drivetrain|wheel ordering/.test(t))return make("Drivetrain power calculations","Run forward, strafe, and turn combinations. Change one input at a time and compare all four outputs.",'public class Main {\n    static double[] mecanum(double forward, double strafe, double turn) {\n        double fl = forward + strafe + turn;\n        double bl = forward - strafe + turn;\n        double fr = forward - strafe - turn;\n        double br = forward + strafe - turn;\n        double max = Math.max(1.0, Math.max(Math.max(Math.abs(fl), Math.abs(bl)), Math.max(Math.abs(fr), Math.abs(br))));\n        return new double[] {fl / max, bl / max, fr / max, br / max};\n    }\n    public static void main(String[] args) {\n        for (double p : mecanum(0.5, 0.2, 0.1)) System.out.println(p);\n    }\n}',[["fl = forward + strafe + turn","Combines the three driver inputs for the front-left wheel using this chosen sign convention."],["bl = forward - strafe + turn","Calculates the back-left wheel command."],["fr = forward - strafe - turn","Calculates the front-right wheel command."],["br = forward + strafe - turn","Calculates the back-right wheel command."],["Math.max(1.0, ...)","Finds a normalization divisor that is never smaller than 1.0."],["new double[] {...}","Returns all four normalized powers in the documented wheel order."]],"This is only the math layer. Confirm motor order, motor direction, roller orientation, and field-centric heading convention on your team's robot.");
  if(/sensor|distance|touch|color|imu|heading|orientation|april.?tag|vision|camera|localization|pose/.test(t))return make("Sensor readings and decision logic","Change the simulated readings and threshold. Test values below, at, and above the threshold.",'public class Main {\n    static String classifyDistance(double centimeters, boolean valid) {\n        if (!valid || Double.isNaN(centimeters)) return "INVALID";\n        if (centimeters < 8.0) return "NEAR";\n        if (centimeters < 25.0) return "IN_RANGE";\n        return "FAR";\n    }\n    public static void main(String[] args) {\n        System.out.println(classifyDistance(5.0, true));\n        System.out.println(classifyDistance(15.0, true));\n        System.out.println(classifyDistance(Double.NaN, false));\n    }\n}',[["boolean valid","Tracks whether the sensor reading should be trusted."],["Double.isNaN(centimeters)","Detects a not-a-number reading before comparing it."],["centimeters < 8.0","Checks the nearest range first, so the more specific condition has priority."],["centimeters < 25.0","Checks the next range after the near case was excluded."],["return \"FAR\";","Provides a final classification for all remaining valid readings."]],"For real FTC sensors, use the SDK sensor class and explicit units. Validate readings and label telemetry with units and coordinate frames.");
  if(/pid|heading hold|controller/.test(t))return make("PID controller calculation","Change target and measurement. Observe the error and output. This is a simplified one-step calculation, not a tuned robot controller.",'public class Main {\n    static double pidOutput(double target, double measured, double kP, double min, double max) {\n        double error = target - measured;\n        double output = kP * error;\n        return Math.max(min, Math.min(max, output));\n    }\n    public static void main(String[] args) {\n        System.out.println(pidOutput(90.0, 82.0, 0.04, -1.0, 1.0));\n        System.out.println(pidOutput(90.0, 110.0, 0.04, -1.0, 1.0));\n    }\n}',[["target - measured","Calculates the control error. Positive and negative signs must match the chosen motor convention."],["kP * error","The proportional term scales the current error into a requested output."],["Math.min(max, output)","Limits output to the configured maximum."],["Math.max(min, ...)","Applies the minimum limit as well."],["return ...;","Returns the bounded controller output."]],"A complete PID controller also tracks integral and derivative terms, elapsed time, reset behavior, and anti-windup. Tune using measured data and team-approved tests.");
  if(/autonomous|trajectory|roadrunner|action|waypoint|motion profile|recovery|match strategy/.test(t))return make("Autonomous action sequencing","Run the small action sequence and change the order. Think about what should happen if a step times out.",'public class Main {\n    enum Step { DRIVE_TO_SAMPLE, INTAKE, PARK, DONE }\n    static Step next(Step current, boolean finished) {\n        if (!finished) return current;\n        switch (current) {\n            case DRIVE_TO_SAMPLE: return Step.INTAKE;\n            case INTAKE: return Step.PARK;\n            case PARK: return Step.DONE;\n            default: return Step.DONE;\n        }\n    }\n    public static void main(String[] args) {\n        Step step = Step.DRIVE_TO_SAMPLE;\n        for (int i = 0; i < 4; i++) {\n            System.out.println(step);\n            step = next(step, true);\n        }\n    }\n}',[["enum Step {...}","Names each autonomous stage so the sequence is readable."],["if (!finished) return current;","Keeps the current action active until its completion condition is true."],["switch (current)","Chooses the next stage based on the current stage."],["return Step.INTAKE;","Advances to the next named action."],["Step.DONE","Represents completion explicitly rather than relying on a magic number."]],"In FTC autonomous, actions must be non-blocking, respect the match time budget, and define timeout/recovery paths. Road Runner APIs vary by project version.");
  if(/test|simulation|regression|hardware.in.the.loop/.test(t))return make("Testing robot logic with repeatable cases","Add another test case and compare actual output with expected output.",'public class Main {\n    static double normalize(double value) {\n        double max = Math.max(1.0, Math.abs(value));\n        return value / max;\n    }\n    static void check(String name, double actual, double expected) {\n        boolean pass = Math.abs(actual - expected) < 0.0001;\n        System.out.println((pass ? "PASS " : "FAIL ") + name + " actual=" + actual);\n    }\n    public static void main(String[] args) {\n        check("small value", normalize(0.4), 0.4);\n        check("large value", normalize(2.0), 1.0);\n        check("negative value", normalize(-3.0), -1.0);\n    }\n}',[["normalize(double value)","Separates the calculation from the hardware so it can be tested on a computer."],["Math.max(1.0, Math.abs(value))","Chooses a divisor that prevents values larger than one while leaving smaller values unchanged."],["check(...)","Defines a small test helper with a name, actual result, and expected result."],["Math.abs(actual - expected) < 0.0001","Compares floating-point values with a tolerance instead of requiring exact decimal equality."],["PASS / FAIL","Makes the test result obvious in the console."]],"Test pure Java calculations and state transitions before connecting them to hardware. Hardware-in-the-loop testing must follow team safety procedures.");
  if(/git|merge conflict|code review|release checklist|configuration audit|performance|memory|refactor|integration/.test(t))return make("Readable, maintainable robot code","Use a small method and named constants. Change the value in one place and observe how the method uses it.",'public class Main {\n    private static final double DRIVE_LIMIT = 0.60;\n    static double requestedDrive(double joystick) {\n        return Math.max(-DRIVE_LIMIT, Math.min(DRIVE_LIMIT, joystick));\n    }\n    public static void main(String[] args) {\n        System.out.println(requestedDrive(0.9));\n        System.out.println(requestedDrive(-0.4));\n    }\n}',[["private static final double DRIVE_LIMIT","A named constant keeps a tuning value in one place and prevents accidental reassignment."],["requestedDrive(double joystick)","A focused method has one responsibility and a clear input."],["Math.min(DRIVE_LIMIT, joystick)","Applies the upper limit."],["Math.max(-DRIVE_LIMIT, ...)","Applies the lower limit."],["main(...)","Runs a couple of checks without needing FTC hardware."]],"Use small commits, clear names, code review, and regression tests. Verify changes on the correct branch before competition releases.");
  if(/run_to_position|position move/.test(t))return make("RUN_TO_POSITION target logic","Change the target and current encoder positions. See when the simulated move is complete.",'public class Main {\n    static boolean isMoveComplete(int target, int current, int tolerance) {\n        return Math.abs(target - current) <= tolerance;\n    }\n    public static void main(String[] args) {\n        System.out.println(isMoveComplete(1200, 1195, 10));\n        System.out.println(isMoveComplete(1200, 900, 10));\n    }\n}',[["target - current","Calculates the remaining encoder error."],["Math.abs(...)","Uses the magnitude so either direction can be checked."],["<= tolerance","Treats the move as complete when the remaining error is inside the allowed tolerance."],["return ...;","Returns true when the target is close enough, otherwise false."]],"In FTC RUN_TO_POSITION, set the target position, choose the run mode and power, then monitor isBusy or an error tolerance without blocking the OpMode loop.");
  if(/non.blocking timing|elapsedtime|elapsed time|time budget/.test(t))return make("Non-blocking elapsed-time logic","Change the duration and sample times. The loop can keep doing other work between checks.",'public class Main {\n    static String timerState(double elapsedSeconds, double durationSeconds) {\n        if (elapsedSeconds < 0.0) return "INVALID TIME";\n        if (elapsedSeconds >= durationSeconds) return "COMPLETE";\n        return "RUNNING";\n    }\n    public static void main(String[] args) {\n        System.out.println(timerState(0.4, 1.0));\n        System.out.println(timerState(1.2, 1.0));\n    }\n}',[["elapsedSeconds","Represents time that has passed since a timer was reset."],["elapsedSeconds < 0.0","Rejects an invalid negative duration."],["elapsedSeconds >= durationSeconds","Checks whether the requested interval has finished."],["return \"RUNNING\";","Reports that the action is still in progress without pausing the program."]],"In FTC, use ElapsedTime.seconds() and compare it each OpMode loop. Avoid Thread.sleep for normal mechanism timing because it blocks other updates.");
  if(/driver feedback|rumble/.test(t))return make("Driver feedback events","Inspect the event condition and cooldown logic. This example models a one-time feedback event without repeatedly firing it.",'public class Main {\n    static boolean shouldNotify(boolean eventActive, boolean alreadyNotified) {\n        return eventActive && !alreadyNotified;\n    }\n    public static void main(String[] args) {\n        System.out.println(shouldNotify(true, false));\n        System.out.println(shouldNotify(true, true));\n        System.out.println(shouldNotify(false, false));\n    }\n}',[["eventActive && !alreadyNotified","Requires a new event and prevents repeating the notification after it has already been sent."],["return ...;","Returns whether the event should trigger feedback on this loop."],["alreadyNotified","Stores whether this event has already been handled; reset it when a new event begins."]],"FTC Gamepad rumble methods are SDK-specific. Trigger feedback only for meaningful events and avoid distracting the driver during a match.");
  if(/safety stop|neutral state|stop method/.test(t))return make("Neutral outputs and stop behavior","Run the sample and check that every inactive or invalid state returns a neutral output.",'public class Main {\n    static double safePower(boolean active, boolean valid, double request) {\n        if (!active || !valid) return 0.0;\n        return Math.max(-1.0, Math.min(1.0, request));\n    }\n    public static void main(String[] args) {\n        System.out.println(safePower(true, true, 0.6));\n        System.out.println(safePower(false, true, 0.6));\n        System.out.println(safePower(true, false, 0.6));\n    }\n}',[["!active || !valid","Checks whether the mechanism is inactive or its input is not valid."],["return 0.0;","Returns a neutral command if either safety condition fails."],["Math.max / Math.min","Clips a valid request to the allowed motor-power range."],["safePower(...)","Each test case demonstrates a normal, inactive, or invalid condition."]],"Every FTC subsystem should have a clear stop method and neutral output behavior. The OpMode should stop issuing commands when it is no longer active.");
  if(/unit conversion/.test(t))return make("Unit conversion helpers","Change the input distance and convert it back to confirm the formulas.",'public class Main {\n    static double inchesToCm(double inches) {\n        return inches * 2.54;\n    }\n    static double degreesToRadians(double degrees) {\n        return degrees * Math.PI / 180.0;\n    }\n    public static void main(String[] args) {\n        System.out.println(inchesToCm(12.0));\n        System.out.println(degreesToRadians(90.0));\n    }\n}',[["inches * 2.54","Converts inches to centimeters using the exact conversion factor."],["degrees * Math.PI","Converts the degree angle into the numerator of the radians formula."],["/ 180.0","Completes degrees-to-radians conversion."],["static double","Declares reusable conversion methods that return decimal values."]],"Choose one unit system at each API boundary. FTC IMU angles may use radians or degrees depending on the API call; label values and convert explicitly.");
  if(/match configuration|alliance data/.test(t))return make("Autonomous match configuration","Change the selected alliance and starting tile. Notice how one enum selects the configuration.",'public class Main {\n    enum Alliance { RED, BLUE }\n    enum StartTile { LEFT, RIGHT }\n    static String routeName(Alliance alliance, StartTile tile) {\n        return alliance.name() + "_" + tile.name() + "_START";\n    }\n    public static void main(String[] args) {\n        System.out.println(routeName(Alliance.RED, StartTile.LEFT));\n        System.out.println(routeName(Alliance.BLUE, StartTile.RIGHT));\n    }\n}',[["enum Alliance","Restricts alliance selection to RED or BLUE rather than arbitrary text."],["enum StartTile","Restricts the start location to the supported options."],["routeName(...)","Combines two explicit selections into a route identifier."],["alliance.name()","Returns the enum constant's name as a String."]],"Show the selected alliance and start position during the FTC init phase. Verify the selection before autonomous starts.");
  if(/dashboard|live tuning/.test(t))return make("Tuning values and live dashboard concepts","Change the tuning values and observe the output. Keep the configuration separate from the calculation.",'public class Main {\n    static class DriveTuning {\n        double maxSpeed = 0.65;\n        double turnScale = 0.8;\n    }\n    static double driveCommand(double stick, DriveTuning tuning) {\n        return Math.max(-tuning.maxSpeed, Math.min(tuning.maxSpeed, stick * tuning.turnScale));\n    }\n    public static void main(String[] args) {\n        DriveTuning tuning = new DriveTuning();\n        System.out.println(driveCommand(1.0, tuning));\n    }\n}',[["class DriveTuning","Groups related tuning values into one configuration object."],["double maxSpeed","Sets the maximum allowed drive command."],["double turnScale","Scales the input before it is limited."],["driveCommand(...)","Uses the tuning object instead of hard-coding values throughout the control method."],["new DriveTuning()","Creates the configuration with its default values."]],"FTC Dashboard integration is project/version-specific. Keep tunable values bounded, documented, and tested before using them in a match.");
  if(/capstone|complete ftc control system/.test(t))return make("Capstone: combine a small robot control system","Run the pure Java decision and power logic first. Then identify which parts would be connected to FTC hardware in your TeamCode project.",'public class Main {\n    static double intakePower(double right, double left) {\n        if (right > 0.05) return 1.0;\n        if (left > 0.05) return -1.0;\n        return 0.0;\n    }\n    static double clip(double value, double limit) {\n        return Math.max(-limit, Math.min(limit, value));\n    }\n    public static void main(String[] args) {\n        double intake = intakePower(0.8, 0.0);\n        double drive = clip(0.9, 0.6);\n        System.out.println("Intake: " + intake);\n        System.out.println("Drive: " + drive);\n    }\n}',[["intakePower(...)","Converts two operator inputs into one signed intake command."],["if (right > 0.05)","Checks the forward trigger first, giving it priority."],["return -1.0;","Returns full reverse power only when the reverse trigger is active and forward is not."],["clip(...)","Keeps a drive request inside the configured limit."],["main(...)","Runs both independent logic helpers and prints their outputs."]],"In the FTC project, map hardware once, call these pure helpers from an active OpMode loop, send outputs to the correct motors, add telemetry, and implement a stop method. Validate the hardware mapping and robot behavior with your team.");
  return make("Java logic for "+l.title,"Study the method, then modify its input and output. Replace the example values with the values required by this lesson and add at least two tests.",'public class Main {\n    static double calculate(double input) {\n        double result = input;\n        if (result < 0.0) {\n            result = 0.0;\n        }\n        return result;\n    }\n    public static void main(String[] args) {\n        System.out.println(calculate(-0.5));\n        System.out.println(calculate(0.4));\n    }\n}',[["static double calculate(double input)","Declares a method with one decimal input and one decimal return value."],["double result = input;","Copies the parameter into a local variable so the calculation can adjust it."],["if (result < 0.0)","Checks a condition and runs the block only when the result is negative."],["result = 0.0;","Updates the local result when the condition is true."],["return result;","Sends the finished value back to the caller."],["System.out.println(calculate(...));","Calls the method and prints the returned value so you can verify the behavior."]],"Connect this tested Java logic to the relevant FTC SDK class only after identifying the correct hardware API, lifecycle, units, and failure behavior.");
 }
 function lessonTeaching(l){
  const sample=codeLessonFor(l);
  const title=l.title.toLowerCase();
  const profiles=[
   {match:/project structure|android studio|gradle|packages|imports/,why:"A correct project layout is part of making robot code buildable. The TeamCode module, Java package, imports, SDK dependency, and build configuration must agree.",extra:"Trace the path from an OpMode source file to the TeamCode module and the Android build. A browser Java example proves only the language logic; it does not build an FTC Robot Controller app.",common:["Putting an OpMode outside the TeamCode source set.","Confusing a Java compiler error with a Gradle sync or dependency error.","Copying SDK imports into the standard-Java browser compiler and expecting them to resolve."]},
   {match:/opmode|linearopmode|iterative|lifecycle|hardwaremap|robot configuration/,why:"An FTC OpMode has a defined lifecycle. Hardware is mapped during initialization, start is controlled by the driver station, the active loop must remain responsive, and outputs must be stopped when the OpMode ends.",extra:"Separate initialization from repeated control. In LinearOpMode, understand waitForStart() and opModeIsActive(); in iterative OpModes, understand init(), start(), loop(), and stop(). Never hide long blocking work inside the control loop.",common:["Using hardware before it has been mapped.","Running a long loop that ignores the OpMode stop request.","Using a made-up hardware name that does not match Robot Configuration."]},
   {match:/motor|run mode|zero.power|encoder|ticks|distance move|turn target|position move/,why:"Motor code combines electrical configuration, mechanical direction, encoder feedback, and control logic. A correct formula still fails if the encoder scale, gear ratio, wheel size, or motor direction is wrong.",extra:"Keep requested power, target position, current position, and completion tolerance as separate values. State the units of every measurement and verify the motor/encoder specifications for the exact hardware revision.",common:["Mixing motor rotations with wheel rotations.","Changing direction in several places instead of defining one consistent convention.","Blocking until a motor finishes instead of continuing to update the OpMode."]},
   {match:/servo|claw|end effector/,why:"Servo positions are commands, not guaranteed physical angles. Linkage geometry, mounting, and mechanical stops determine what a numeric position means on the actual robot.",extra:"Store named positions such as OPEN, HOLD, and CLOSED. Calibrate a conservative usable range and keep the mechanism from being driven against a hard stop.",common:["Assuming 0.0 and 1.0 are safe physical endpoints.","Using a continuous-rotation servo as if it were a positional servo.","Scattering unexplained position numbers throughout an OpMode."]},
   {match:/gamepad|trigger|button|toggle|deadzones|deadzone|joystick|input/,why:"Driver input is noisy and changes every loop. Good control code converts raw axes and button states into intentional commands, with predictable neutral behavior.",extra:"Distinguish a button being held from a new press edge. Apply a deadzone before scaling, preserve the sign of the stick, and test neutral, partial, and full inputs.",common:["Toggling a state every loop while a button is held.","Forgetting that stick axes can be slightly non-zero at rest.","Applying a deadzone without rescaling the remaining input range."]},
   {match:/mecanum|field.centric|tank drive|arcade drive|drivetrain|wheel ordering/,why:"A drivetrain mixes forward, strafe, and rotation commands into wheel outputs. The math must match the physical wheel order, motor directions, and coordinate frame of the robot.",extra:"Normalize wheel powers using the largest absolute output so the ratios are preserved. Field-centric control also requires a valid heading and a consistent field/robot coordinate convention.",common:["Using a wheel order that does not match the hardware mapping.","Clipping each wheel independently and changing the intended movement ratios.","Mixing degrees and radians or reversing the heading sign in field-centric math."]},
   {match:/subsystem|hardware class|command and action|architecture|encapsulation|constructor|class|object/,why:"Object-oriented design helps the team separate hardware ownership from decisions about what the robot should do. A focused subsystem class is easier to reuse, test, and review than a single giant OpMode.",extra:"Keep hardware references private, initialize them deliberately, and expose a small public interface such as drive(), setTarget(), update(), and stop(). Prefer passing dependencies into a class over relying on hidden global state.",common:["Making every field public so any class can change it.","Putting all robot behavior in one oversized OpMode.","Creating a second hardware mapping path that disagrees with the main robot configuration."]},
   {match:/state machine|state transition|non.blocking|elapsedtime|elapsed time|timing/,why:"Mechanisms often need to perform several actions while driver input and telemetry continue updating. State machines and elapsed-time checks let the robot make progress without freezing its control loop.",extra:"Each state should define its entry behavior, update behavior, exit condition, timeout, and fallback. Use elapsed-time comparisons rather than sleeping through an action.",common:["Changing state without defining the output for the new state.","Forgetting a timeout when a sensor never reports completion.","Using Thread.sleep() for a normal mechanism sequence."]},
   {match:/sensor|distance|touch|color|imu|heading|orientation|april.?tag|vision|camera|localization|pose/,why:"Sensors provide measurements, not perfect truth. Robot code must validate readings, label units, understand coordinate frames, and decide what to do when a reading is missing or implausible.",extra:"Keep sensor reading, validation, filtering, and decision-making as separate steps. For orientation and vision, document axes, angle units, camera mounting, and the reference frame used by the SDK.",common:["Comparing readings with different units.","Treating a missing or invalid reading as a real zero.","Using a heading or pose value without checking its coordinate frame."]},
   {match:/pid|heading hold|controller|motion profile|trajectory constraints/,why:"Feedback control compares a target with a measured value and adjusts output based on error. Reliable tuning requires repeatable measurements, bounded outputs, and a clear sign convention.",extra:"Start with a simple proportional calculation, then understand integral accumulation, derivative rate, elapsed time, output limits, reset behavior, and integral windup before using a full controller.",common:["Tuning several gains at the same time.","Ignoring output saturation or integral windup.","Using an inconsistent sign convention for error and motor correction."]},
   {match:/autonomous|trajectory|roadrunner|action|waypoint|recovery|match strategy|alliance/,why:"Autonomous code is a sequence of decisions and actions under a fixed match time budget. It must account for localization uncertainty, action completion, and recovery when an assumption fails.",extra:"Represent stages explicitly, track elapsed time, define timeouts, and reserve time for the final action. Road Runner APIs vary by version, so check the version used by your team project before copying API calls.",common:["Assuming an action always finishes successfully.","Using hard-coded waits instead of checking completion conditions.","Forgetting a fallback when vision, localization, or a mechanism step fails."]},
   {match:/telemetry|logging|diagnostic|debugging|compiler error|exception|null check|defensive/,why:"Debugging works best when the program exposes the smallest set of facts needed to explain its behavior. A clear error message is more useful than silently continuing with invalid data.",extra:"Read the first meaningful compiler error, inspect the named file and line, then fix the root cause. At runtime, log state changes and unit-labelled values without flooding the Driver Station.",common:["Fixing later compiler messages before the first root error.","Catching every exception and ignoring it.","Printing so much telemetry that important values become hard to find."]},
   {match:/test|simulation|regression|hardware.in.the.loop/,why:"A robot change should be tested against expected behavior, not judged only by whether it compiles. Pure Java logic can be tested without hardware, then validated with controlled robot tests.",extra:"Write test cases for normal values, boundaries, invalid inputs, and state transitions. For decimal results, compare with a tolerance rather than exact equality.",common:["Testing only one happy-path input.","Using exact equality for floating-point calculations.","Claiming a physical robot test when only a browser simulation was run."]},
   {match:/git|merge conflict|code review|release checklist|configuration audit|performance|memory|refactor|integration|capstone/,why:"Competition code is a team product. Clear ownership, small changes, repeatable tests, and a known release version reduce last-minute surprises.",extra:"Keep changes focused, review the diff, preserve a known-good version, and run regression checks after integration. Measure performance before optimizing and keep the control loop predictable.",common:["Committing unrelated changes together.","Resolving a merge conflict by blindly choosing one side.","Releasing code without recording the tested commit and robot configuration."]}
  ];
  const profile=profiles.find(p=>p.match.test(title+" "+l.body+" "+l.task));
  const topicExtra=profile?.extra||"Break the topic into inputs, processing, outputs, and failure cases. Trace one normal example by hand, then test a boundary case and an invalid or unexpected input.";
  const common=profile?.common||["Using unclear variable names or unexplained numeric values.","Testing only the normal case and ignoring boundaries or invalid input.","Mixing the calculation with hardware access, making the logic harder to test."];
  const why=profile?.why||"This concept matters because FTC robot code must be understandable, testable, and predictable under match conditions.";
  const concept=l.body+"\n\nDeeper walkthrough: "+topicExtra+" Start by identifying the data entering this code, the decision or calculation it performs, and the result another part of the robot will use.";
  return {sample,goal:"By the end, you should be able to explain "+l.title.toLowerCase()+", trace the sample code, modify the implementation, and defend your test cases.",concept,why,walkthrough:sample.lines,practice:sample.task,common,integration:sample.integration};
 }
 function mountCodeWorkspace(l){
  const host=document.getElementById("advCodeWorkspace");if(!host)return;
  const sample=codeLessonFor(l);let tab="task";
  host.innerHTML='<div class="ftc-workspace"><div class="ftc-workspace-left"><div class="ftc-workspace-tabs"><button class="active" data-code-tab="task">Task</button><button data-code-tab="checks">Checks</button><button data-code-tab="hints">Hints</button></div><div id="ftcWorkspaceTab"><h3>'+esc(sample.name)+'</h3><p>'+esc(sample.task)+'</p><h4>Objectives</h4><ol><li>Read the example and understand each method.</li><li>Change the code to satisfy the task.</li><li>Compile and run your edited Java source.</li></ol><h4>FTC SDK connection</h4><p>'+esc(sample.integration)+'</p></div></div><div class="ftc-workspace-right"><div class="ftc-editor-top"><b>OnBot Java · Java editor</b><span>Main.java</span></div><textarea id="ftcCodeEditor" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="Editable Java source">'+esc(sample.code)+'</textarea><div class="ftc-editor-actions"><button class="btn btn-primary" id="ftcCompile">Compile &amp; Run</button><button class="btn btn-soft" id="ftcCodeReset">Reset</button><button class="btn btn-soft" type="button" data-save-code="#ftcCodeEditor" data-code-title="FTC Academy Java project">Save this code to your Code Library</button><span id="ftcCompileStatus">Ready</span></div><div class="ftc-console"><b>Console / compiler output</b><pre id="ftcCompileOutput">Edit the code, then compile it to check the actual Java source.</pre></div></div></div><div class="ftc-line-teaching"><h3>What each important line does</h3>'+sample.lines.map((x,i)=>'<article><code>'+esc(x[0])+'</code><p>'+esc(x[1])+'</p></article>').join("")+'</div><p class="ftc-compiler-note">Compiler note: this checks standard Java source using an online Java compiler. FTC SDK imports and hardware classes require the FTC Robot Controller SDK/OnBotJava environment; this browser compiler cannot certify an FTC APK or hardware configuration. Source is sent to the Piston compiler service when you press Compile &amp; Run.</p>';
  host.querySelectorAll("[data-code-tab]").forEach(b=>b.addEventListener("click",()=>{tab=b.dataset.codeTab;host.querySelectorAll("[data-code-tab]").forEach(x=>x.classList.toggle("active",x===b));const pane=host.querySelector("#ftcWorkspaceTab");if(tab==="task")pane.innerHTML="<h3>"+esc(sample.name)+"</h3><p>"+esc(sample.task)+"</p><h4>Objectives</h4><ol><li>Read the example and understand each method.</li><li>Change the code to satisfy the task.</li><li>Compile and run your edited Java source.</li></ol>";if(tab==="checks")pane.innerHTML="<h3>Code checks</h3><p>Before submitting, confirm:</p><ul><li>Your source compiles without errors.</li><li>The method handles normal, minimum, and maximum inputs.</li><li>You tested the output against expected results.</li><li>You understand which values must be tuned for your robot.</li></ul>";if(tab==="hints")pane.innerHTML="<h3>Hints</h3><p>Start with the method signature. Trace the conditions in order. Remember that an early return exits the method immediately. Use the console to inspect each test result.</p><p>"+esc(sample.integration)+"</p>";}));
  host.querySelector("#ftcCodeReset").addEventListener("click",()=>{host.querySelector("#ftcCodeEditor").value=sample.code;host.querySelector("#ftcCompileOutput").textContent="Starter code restored.";host.querySelector("#ftcCompileStatus").textContent="Ready";});
  host.querySelector("#ftcCompile").addEventListener("click",async()=>{
  const code=host.querySelector("#ftcCodeEditor").value.trim(),button=host.querySelector("#ftcCompile"),out=host.querySelector("#ftcCompileOutput"),status=host.querySelector("#ftcCompileStatus");
  if(!code){out.textContent="Write Java code before compiling.";return;}
  button.disabled=true;status.textContent="Compiling…";out.textContent="Sending your Java source to the secure compiler…";
  try{
    if(typeof window.rangersCompileJava!=="function")throw new Error("Compiler connection is not ready. Refresh the page and sign in.");
    const response=await window.rangersCompileJava({code,stdin:""});
    if(response.error)throw new Error(response.error.message||"Compiler request failed.");
    const result=response.data||{},c=result.compile||{},r=result.run||{},parts=[];
    if(c.output)parts.push("COMPILER\n"+c.output);
    if(r.output)parts.push("PROGRAM OUTPUT\n"+r.output);
    if(c.code!==0&&c.code!==undefined){status.textContent="Compile error";out.textContent=parts.join("\n\n")||"Compilation failed.";}
    else if(r.code!==0&&r.code!==undefined){status.textContent="Runtime error";out.textContent=(parts.join("\n\n")||"Program stopped with an error.")+"\nExit code: "+r.code;}
    else{status.textContent="Compiled successfully";out.textContent=parts.join("\n\n")||"Compiled and ran successfully. No output was produced.";}
  }catch(error){status.textContent="Compiler unavailable";out.textContent=error.message||"The compiler could not complete this request.";}
  finally{button.disabled=false;}
});
 }
 const cadFirstTenGuides=[
  {intro:"A well-organized Onshape document is the foundation of a team CAD workflow. Documents contain tabs such as Part Studios, Assemblies, and Drawings; versions preserve important milestones; branches let teammates explore changes without overwriting the stable design.",why:"FTC robots change quickly. Clear document names, version history, and ownership help the team find the correct design before manufacturing and recover when an experiment does not work.",steps:["Create a document with a season, robot, and subsystem name. Avoid names such as Untitled or Final Final.","Create separate, clearly named tabs for the chassis, mechanisms, assemblies, and drawings where that separation makes the project easier to navigate.","Add a short description that states the design purpose, units, and hardware revision being modeled.","Create a version before a major design change. Use a descriptive version name that explains what changed.","Review sharing permissions with the team and agree on who owns the source document and who reviews changes."],challenge:"Set up a clean FTC robot document. Add a chassis tab and one mechanism tab, create a named version, and write a short handoff note so another teammate can find the correct starting point.",deliverable:"A screenshot of the document tab bar, a named version, and a short explanation of your naming and versioning choices.",mistakes:["Putting every unrelated part into one unnamed tab.","Using version names that do not explain what changed.","Assuming a shared link automatically gives every teammate the correct edit permissions."],checks:["The document and tabs have clear names.","A meaningful version checkpoint exists.","A teammate could identify the current design and its purpose."]},
  {intro:"A sketch plane determines the orientation of the geometry you create. Choosing a plane that matches the part's functional orientation makes dimensions, extrusions, and later edits easier to understand.",why:"A bracket or plate is easier to edit when its main profile is sketched from the view that defines its important interfaces. A poor plane choice can create confusing rotations and references.",steps:["Identify the part's primary face and the direction in which thickness or depth will be added.","Choose the origin plane that best matches that functional view; use an existing planar face only when the reference is stable and intentional.","Create a simple rectangle or bracket profile and add the dimensions that define its position relative to the origin.","Finish the sketch and create a small test extrusion to confirm the orientation.","Repeat the same part from a different plane and compare which version is easier to dimension and assemble."],challenge:"Model a simple sensor bracket twice using two different sketch planes. Compare the orientation, dimensions, and ease of editing, then keep the clearer version.",deliverable:"Two screenshots showing the plane choices and a short comparison naming the plane you selected and why.",mistakes:["Choosing a plane only because it is the first one visible.","Building critical geometry from a temporary face that may disappear after an upstream edit.","Forgetting how the sketch orientation affects the later extrusion direction."],checks:["The chosen plane matches the part's functional orientation.","The sketch is located predictably relative to the origin.","The resulting solid has the intended orientation."]},
  {intro:"Sketch constraints describe relationships between geometry. Dimensions define exact sizes; geometric constraints define relationships such as horizontal, vertical, coincident, equal, tangent, and perpendicular.",why:"A sketch that is only positioned by dragging can shift unexpectedly. Constraints preserve design intent when a dimension changes or a feature is reused.",steps:["Draw a simple plate outline with lines and circles for mounting holes.","Apply coincident constraints where endpoints should connect and horizontal or vertical constraints to align edges.","Use equal constraints only when two features are intended to stay the same size.","Add dimensions for the functional width, height, hole diameter, and hole spacing.","Check the sketch's constraint status. Change one driving dimension and verify the geometry updates without losing the intended relationships."],challenge:"Create a fully constrained mounting plate sketch with four holes. Use geometric constraints for alignment and dimensions for size and hole spacing.",deliverable:"A screenshot of the fully constrained sketch and a note explaining at least four constraints you used.",mistakes:["Adding dimensions that conflict with existing constraints.","Using dimensions to force relationships that a geometric constraint expresses more clearly.","Leaving important geometry under-constrained and relying on its current screen position."],checks:["Connected geometry has coincident relationships where needed.","Horizontal, vertical, equal, or other relationships are intentional.","Functional dimensions are driving the design and the sketch remains stable after an edit."]},
  {intro:"Dimension strategy is about choosing measurements that control function. A useful sketch is dimensioned from datums, centerlines, mounting faces, and interfaces rather than from arbitrary edges.",why:"The location of a motor, bearing, sensor, or fastener pattern matters more than the visual appearance of a shape. Functional dimensions make the design easier to verify against hardware.",steps:["Identify the mounting face, centerline, shaft axis, or other datum that controls how the part fits the robot.","Record the required dimensions and their source: manufacturer drawing, measured hardware, or a team design decision.","Dimension hole centers and important edges from the datum instead of chaining many edge-to-edge dimensions.","Avoid duplicate dimensions that attempt to control the same geometry twice.","Change a controlling dimension and verify that the part updates while the important interfaces remain aligned."],challenge:"Dimension a motor mounting plate from its mounting face and centerline. Include the motor interface, hole spacing, edge margins, and units.",deliverable:"A dimensioned sketch plus a small table listing each critical dimension and where its value came from.",mistakes:["Measuring from an edge that is not a functional reference.","Mixing inches and millimeters without labeling units.","Adding redundant dimensions that over-constrain the sketch."],checks:["A clear datum or centerline controls the layout.","Critical dimensions have units and a source.","No duplicate or conflicting dimensions remain."]},
  {intro:"Construction geometry is reference geometry used to control a sketch without becoming part of the finished solid. Centerlines, pitch circles, and guide lines help define alignment and repeated features.",why:"Robot parts often need hole patterns centered on shafts, bearings, or rails. Construction geometry makes those relationships visible and editable.",steps:["Start a sketch and create a centerline through the origin or the functional center of the part.","Toggle the line to construction geometry so it guides the sketch but does not become a profile edge.","Use a pitch circle or construction rectangle to locate hole centers at consistent offsets.","Dimension the reference geometry from the origin and add coincident relationships to the feature centers.","Edit the pitch diameter or spacing and verify all dependent holes move together."],challenge:"Create a mounting plate with a centered four-hole pattern controlled by a construction rectangle or pitch circle. Change the spacing once and inspect every hole.",deliverable:"A screenshot showing construction geometry and the final hole pattern, with a note explaining what the reference controls.",mistakes:["Leaving reference lines as solid profile edges.","Using unrelated construction lines that do not control any functional feature.","Manually positioning repeated holes instead of relating them to a common reference."],checks:["Construction geometry is visibly distinguished from profile geometry.","Hole centers are constrained to the reference layout.","A single reference edit updates the intended pattern."]},
  {intro:"Symmetry constraints keep geometry balanced around a centerline. Instead of independently dimensioning matching left and right features, you define one shared relationship.",why:"Symmetric brackets, sensor mounts, and plates are easier to maintain when the centerline controls both sides. A width change can preserve equal margins automatically.",steps:["Draw a centerline through the sketch origin or the part's functional center.","Create one side of the profile and the corresponding geometry on the other side.","Apply a symmetry constraint to matching points or entities around the centerline.","Dimension the overall width and the key offset from the centerline rather than duplicating both sides.","Change the overall width and confirm the two sides remain balanced."],challenge:"Create a symmetric bracket profile around a centerline. Make the overall width a driving dimension and show that both sides update together.",deliverable:"A screenshot of the symmetry constraint and two versions of the sketch at different widths.",mistakes:["Using symmetry around a line that is not the true functional center.","Adding separate dimensions that fight the symmetry relationship.","Mirroring the shape visually but not constraining the mirrored geometry."],checks:["The symmetry axis is intentional and stable.","Matching geometry is controlled by a symmetry relationship.","A width edit preserves equal geometry on both sides."]},
  {intro:"Sketch patterns create repeated geometry from one seed feature. Linear patterns use direction and spacing; circular patterns use a center, quantity, and angular range.",why:"Repeated mounting holes and slots should remain consistent. A pattern is easier to update than individually drawn features.",steps:["Create and fully constrain one seed hole or slot.","Choose a linear or circular pattern based on how the hardware repeats around the part.","Set the pattern direction using a stable axis or construction line.","Enter a clear quantity and spacing or angular range, then inspect the preview before accepting.","Change the quantity or spacing and verify the pattern stays inside the part's usable boundary."],challenge:"Build a four-hole mounting pattern with a clear quantity and spacing control. Then change it to a different quantity and confirm the layout remains centered.",deliverable:"A screenshot of the pattern settings and the updated pattern after changing one parameter.",mistakes:["Patterning geometry that is not fully constrained.","Choosing a direction that depends on an unstable edge.","Forgetting to check edge distance and fastener access after increasing the pattern count."],checks:["The seed feature is fully constrained.","Pattern direction, quantity, and spacing are explicit.","The updated pattern remains within the part boundary."]},
  {intro:"Sketch mirroring creates a matching copy across a defined mirror line. It is especially useful for profiles with two sides that must remain identical.",why:"Mirroring avoids redrawing matching geometry and reduces the number of independent dimensions that can drift apart.",steps:["Create a stable construction centerline to act as the mirror axis.","Fully constrain the original side of the profile before mirroring it.","Select only the geometry that should be copied; do not include unrelated construction references.","Apply the mirror operation and inspect the coincident connections at the centerline.","Change a dimension on the original side and verify the mirrored side updates consistently."],challenge:"Create one half of a symmetric bracket, mirror it across a centerline, and change the bracket width to prove the two halves remain connected.",deliverable:"A screenshot before and after the mirror operation, plus a note naming the mirror axis.",mistakes:["Mirroring around a temporary edge that may change.","Selecting extra construction geometry and creating duplicate references.","Leaving the original side under-constrained so the mirrored result is unstable."],checks:["The mirror axis is stable and clearly identified.","Only intended geometry is mirrored.","Edits to the source side preserve the mirrored relationship."]},
  {intro:"A slot is a controlled elongated opening. Its width, overall length, end radius, and orientation determine which fasteners fit and how much adjustment is available.",why:"Adjustable sensor brackets and tensioning mounts use slots to allow measured movement. The slot must provide the needed adjustment without weakening the part or blocking tool access.",steps:["Identify the fastener size and the required adjustment direction from the real assembly.","Set slot width from the fastener clearance requirement and keep units explicit.","Dimension the slot centerline and overall length from functional datums.","Calculate the available travel from the slot length and fastener diameter; distinguish total slot length from usable center travel.","Check edge distance, nearby features, washer coverage, and tool access in the finished part."],challenge:"Design an adjustable sensor slot. Record the fastener size, slot width, overall length, usable travel, and minimum edge margin as separate values.",deliverable:"A dimensioned slot sketch and a small calculation table showing how much adjustment the design provides.",mistakes:["Treating overall slot length as usable fastener-center travel.","Choosing a slot width without checking the actual fastener and washer.","Placing the slot so close to an edge that the part may not have enough material."],checks:["Slot dimensions and units are explicit.","Usable travel is calculated rather than guessed.","Fastener clearance and surrounding material are checked."]},
  {intro:"Arcs and tangent transitions create smooth connections between straight edges and curved geometry. Tangency controls the direction at the connection so the profile does not form an unintended corner.",why:"Smooth transitions can improve fit, reduce sharp internal corners, and make a profile easier to manufacture or print. The radius should serve a purpose rather than be added only for appearance.",steps:["Draw the main straight edges and identify where a curved transition is needed.","Create an arc with endpoints that connect to the intended edges.","Apply coincident constraints at the arc endpoints and tangent constraints where the curve should flow smoothly into a line.","Dimension the radius or arc position from a functional reference.","Inspect the profile at high zoom and verify that the arc is connected, tangent, and does not create a self-intersection."],challenge:"Add a rounded transition to a plate profile. Keep the arc tangent to both adjacent edges and record the radius and the reason you selected it.",deliverable:"A screenshot of the tangent constraints and a note explaining how the chosen radius affects the part outline.",mistakes:["Using coincident endpoints without adding tangency where a smooth transition is required.","Adding a radius so large that it removes needed mounting material.","Leaving a tiny gap or overlap between the arc and adjacent edges."],checks:["Arc endpoints are connected to the intended edges.","Tangent constraints create the intended smooth transition.","The radius preserves the part's functional geometry."]}
 ];
 const programmingFirstTenGuides=[
  {concept:"An FTC Android Studio project is a structured set of modules, source folders, resources, build files, and configuration. The project is more than one Java file: the build system uses that structure to find code and assemble the app.",why:"Knowing where code belongs prevents misplaced files and makes it easier to find the OpMode, hardware setup, and reusable classes when the robot project grows.",common:["Editing a generated build file without understanding what it controls.","Saving a Java class outside the package or source folder used by the Robot Controller module.","Renaming a package in one place but not updating the matching folder and references."],integration:"FTC team code is usually organized around the Robot Controller Android project. Keep OpModes, subsystems, utilities, and configuration values in predictable packages."},
  {concept:"Java syntax is the set of rules that makes source code readable to the compiler. Braces define blocks, semicolons end statements, parentheses group expressions and parameters, and capitalization matters in identifiers.",why:"A missing brace or misspelled identifier can prevent an entire OpMode from compiling. Consistent formatting makes errors easier for teammates to review.",common:["Forgetting a semicolon after a statement.","Mismatching opening and closing braces.","Changing capitalization in a class or method name and assuming Java ignores it."],integration:"FTC OpModes are Java classes. Clear class structure and consistent syntax make hardware initialization and control logic easier to maintain."},
  {concept:"Variables store values that can change while a program runs. A data type tells Java what kind of value is allowed: int for whole-number counts, double for measurements, boolean for true/false state, and String for text.",why:"Robot programs use variables for encoder counts, sensor distances, motor commands, and mechanism states. Correct types reduce accidental conversions and unclear calculations.",common:["Using int for a measurement that needs decimals.","Giving a variable a vague name such as x or temp when its purpose matters later.","Reading a variable before assigning a meaningful initial value."],integration:"A robot might store a requested drive speed as a double, a button state as a boolean, and an encoder target as an int. Choose the type that matches the data."},
  {concept:"Constants are values that should not change during normal operation. In Java, final marks a value as assigned once; static makes a class-level value shared rather than tied to one object.",why:"Hardware names, servo positions, speed limits, and tuning values should be easy to find and review. Named constants are safer to update than unexplained numbers scattered throughout methods.",common:["Repeating the same literal value in many places.","Using a constant name that does not describe its unit or purpose.","Changing a value in one method but forgetting another copy elsewhere."],integration:"Store configured motor and servo names in one place, and use descriptive constants for speed scales or mechanism positions. Confirm every hardware name matches the Robot Configuration."},
  {concept:"Operators build expressions from values. Arithmetic operators calculate results, comparison operators produce booleans, and logical operators combine conditions. Operator precedence affects which part of an expression is evaluated first.",why:"Control decisions often combine driver input and sensor state. A misplaced comparison or missing parentheses can make a mechanism respond under the wrong condition.",common:["Using = when == is required for comparison.","Combining conditions without parentheses when the intended grouping is not obvious.","Comparing measurements without checking their units or valid range."],integration:"An FTC program may combine a driver button with a sensor threshold to decide whether to update a mechanism state. Keep each condition readable and test the boundary values."},
  {concept:"An if/else statement chooses which block runs based on a boolean condition. Java evaluates the condition, runs the matching branch, and skips the other branch.",why:"Driver controls and sensor-based decisions depend on clear branches. A well-structured conditional makes the robot's response predictable and easier to debug.",common:["Writing a condition that is always true or always false.","Forgetting braces around a multi-statement branch.","Checking conditions in an order that makes a more specific branch unreachable."],integration:"Use conditionals to select a speed mode, respond to a limit sensor, or choose a safe fallback when a reading is invalid. Test both true and false cases."},
  {concept:"A switch statement selects behavior from one value, while an enum gives meaningful names to a fixed set of states. Together they make state-based logic easier to read than unexplained integer codes.",why:"Mechanisms often have a small set of modes such as IDLE, INTAKING, and SCORING. Named states make transitions and telemetry clearer.",common:["Forgetting break in a traditional switch and accidentally continuing into another case.","Leaving out a default or fallback state.","Using string or numeric labels when a small enum would make the states safer."],integration:"A mechanism controller can store its current state in an enum and use a switch to update outputs. Keep state transitions explicit and test every state."},
  {concept:"Loops repeat work. A for loop is useful when the number of iterations is known, a while loop repeats while a condition remains true, and an enhanced for loop visits each item in a collection.",why:"Loops are useful for processing lists and repeated calculations, but an uncontrolled loop can block an OpMode and stop driver controls or telemetry from updating.",common:["Creating an infinite loop with a condition that never changes.","Using Thread.sleep or long blocking work inside a responsive control loop.","Changing a collection while iterating over it without a safe approach."],integration:"FTC LinearOpMode code commonly has an active loop that continues while the OpMode is active. Keep each pass short so gamepad input, telemetry, and mechanisms stay responsive."},
  {concept:"A method packages a task behind a name. Parameters provide input, the return type describes the result, and return sends a value back to the caller. void means the method does not return a value.",why:"Small methods make robot code easier to test and reuse. A motor-power calculation can be tested independently before it is connected to physical hardware.",common:["Declaring a return type but not returning a value on every required path.","Confusing a parameter with a local variable.","Writing one method that performs too many unrelated jobs."],integration:"Create helper methods for clipping motor power, applying a deadzone, or converting encoder counts. Keep calculations separate from hardware commands when possible."},
  {concept:"Scope determines where a variable can be used. A local variable exists inside its block, a parameter receives a value from the caller, and an instance field belongs to an object.",why:"Understanding scope prevents accidental shadowing and helps you decide whether a value belongs to one method or should be shared by the whole subsystem.",common:["Declaring a local variable with the same name as a field and updating the wrong one.","Trying to use a local variable after its block has ended.","Making every value global or static when it belongs to one robot object."],integration:"A drivetrain object can store its motor references as fields while using local variables for temporary calculations inside drive methods. Pass values as parameters rather than relying on hidden shared state."}
 ];
 function data(){
  const l=lesson(),t=l.task||"Complete the practical activity and document the result.";
  if(current.track==="Programming"){
   const teach=lessonTeaching(l),sample=teach.sample;
  if(current.track==="Programming"&&current.index<programmingFirstTenGuides.length){
   const g=programmingFirstTenGuides[current.index];
   teach.concept=g.concept;teach.why=g.why;teach.common=g.common;teach.integration=g.integration;
  }

   if(current.page===0)return{label:"LESSON · 1 OF 4",title:"Understand "+l.title.toLowerCase(),body:teach.concept,blocks:[["Why FTC programmers use this",teach.why],["The key idea",l.body]],teaching:teach};
   if(current.page===1)return{label:"LESSON · 2 OF 4",title:"Read the Java code line by line",body:"Before editing anything, understand what the example does. Read each explanation, then trace the sample inputs through the method.",steps:["Start with the class and method declaration. Identify the inputs and the value returned.","Read the statements from top to bottom. Track how each variable changes.","For every if, switch, or loop, predict which branch or iteration runs.","Look at the printed test cases and predict the output before running them.","Connect the example to the FTC SDK only after the Java logic makes sense."],blocks:[["Code example",sample.name],["Common mistakes",teach.common.join(" ")],["Where this fits in FTC",teach.integration]],teaching:teach};
   if(current.page===2)return{label:"PRACTICE · 3 OF 4",title:"Edit, compile, and experiment",body:sample.task,blocks:[["Your coding task","Change the starter source. Do not just describe the solution: write Java, compile it, and run test inputs."],["What to produce","A modified Java program, a successful compile/run where appropriate, and a short explanation of your test cases."],["FTC connection",teach.integration]],teaching:teach};
   return{label:"REVIEW · 4 OF 4",title:"Final code review",body:"Use the code you edited on the previous page. Explain the change you made and what the compiler and test output showed. Do not claim a robot hardware test unless you actually performed one.",blocks:[["Practical test",sample.task],["Evidence to include","Name the method or class you changed, describe the logic, give the test inputs, and report the actual output or compiler error."],["FTC integration reminder",teach.integration]],checks:["I can explain the method signature and the role of its parameters.","I can explain at least three important statements or branches in the code.","I changed actual Java source and attempted to compile and run it.","I tested more than one input, including an edge case.","I can explain how this concept connects to FTC code and what still needs SDK/hardware validation."]};
  }
  if(current.track==="CAD"&&current.index<cadFirstTenGuides.length){
   const g=cadFirstTenGuides[current.index];
   if(current.page===0)return{label:"CAD LESSON · 1 OF 4",title:"Understand the design decision",body:g.intro,blocks:[["Why this matters on an FTC robot",g.why]]};
   if(current.page===1)return{label:"CAD LESSON · 2 OF 4",title:"Follow the workflow",body:"Work through each step in Onshape. Pause after each one and inspect the model before continuing.",steps:g.steps,blocks:[["Common mistakes to avoid",g.mistakes.join(" ")] ]};
   if(current.page===2)return{label:"CAD PRACTICE · 3 OF 4",title:"Build a real FTC design artifact",body:g.challenge,blocks:[["What to submit",g.deliverable],["Engineering habit","Use real hardware dimensions where available, label assumptions, and do not treat a CAD fit check as proof that a physical part is safe or functional."]]};
   return{label:"CAD REVIEW · 4 OF 4",title:"Review and document your model",body:"Use your actual Onshape document. Record what you built and the checks you performed; do not claim a measurement or physical test you did not complete.",blocks:[["Practical challenge",g.challenge],["Evidence to include",g.deliverable]],checks:g.checks};
  }
  if(current.page===0)return{label:"LEARN · 1 OF 4",title:"Understand the idea",body:l.body,blocks:[["Why it matters","Good CAD communicates design intent so teammates can build, adjust, and repair the robot."],["Learning goal","Explain "+l.title.toLowerCase()+" and identify where it appears on a real FTC robot."]]};
  if(current.page===1)return{label:"LEARN · 2 OF 4",title:"Work through the method",body:"Follow these steps in order. Inspect the result before moving on.",steps:l.steps};
  if(current.page===2)return{label:"LEARN · 3 OF 4",title:"Guided build challenge",body:t,blocks:[["What to produce","A real Onshape part, assembly, drawing, or design-review artifact. Keep it editable and name features clearly."],["Evidence to collect","Save a screenshot, drawing, dimension table, or test log. You will use it on the final page."]]};
  return{label:"CHECK YOUR WORK · 4 OF 4",title:"Final practical test",body:"Use your actual Onshape document. This checklist reviews your evidence; it cannot directly open Onshape or verify physical fit.",blocks:[["Practical test",t],["Evidence","Describe the feature or assembly you created and a dimension or motion check you performed."]],checks:l.checks||["The result meets the stated design requirements.","Dimensions, references, fit, or motion have been checked.","Evidence and one improvement are documented."]};
 }
 function draw(){
  const l=lesson(),d=data(),id=current.track+"-"+current.index,s=load()[id]||{};
  const pageCount=4;document.getElementById("advTrack").textContent=(current.track==="CAD"?"CAD ACADEMY":"PROGRAMMING ACADEMY")+" · PAGE "+(current.page+1)+" OF "+pageCount;
  document.getElementById("advTitle").textContent=l.title;notesToggle.textContent="✎ Lesson notes";document.getElementById("advDots").innerHTML=Array.from({length:pageCount},(_,n)=>n).map(n=>'<span class="'+(n<=current.page?"on":"")+'"></span>').join("");
  let h='<div class="eyebrow">'+esc(d.label)+'</div><h2>'+esc(d.title)+'</h2><p>'+esc(d.body)+'</p>';
  if(d.steps)h+='<ol>'+d.steps.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ol>';
  if(d.blocks)d.blocks.forEach(x=>h+='<div class="adv-academy-block"><b>'+esc(x[0])+'</b><p>'+esc(x[1])+'</p></div>');
  if(d.teaching&&current.track==="Programming"){
   const teach=d.teaching;
   h+='<section class="lesson-teaching"><h3>Teacher walkthrough</h3><p>'+esc(teach.goal)+'</p><div class="lesson-code-explain"><h4>Code, explained</h4>'+teach.walkthrough.map((x,i)=>'<article><div class="lesson-line-number">'+String(i+1).padStart(2,"0")+'</div><div><code>'+esc(x[0])+'</code><p>'+esc(x[1])+'</p></div></article>').join("")+'</div><div class="lesson-teaching-grid"><section><h4>Common mistakes to avoid</h4><ul>'+teach.common.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul></section><section><h4>How it connects to FTC</h4><p>'+esc(teach.integration)+'</p></section></div></section>';
  }
  if(current.page===2&&current.track==="Programming")h+='<div id="advCodeWorkspace"></div>';
  if(current.page===3){
   const keywords=reviewKeywords(l);
   h+='<label for="advEvidence"><b>Your evidence / test notes</b></label><textarea id="advEvidence" class="adv-academy-evidence" placeholder="What did you build? What did you test? What happened? What would you improve?">'+esc(s.evidence||"")+'</textarea>';
   h+='<div class="adv-academy-block"><b>Topic keyword check</b><p>Use at least '+Math.min(2,keywords.length)+' relevant keywords in your evidence: '+esc(keywords.slice(0,6).join(" · "))+'.</p></div>';
   h+=d.checks.map((x,i)=>'<label class="adv-academy-check"><input type="checkbox" data-adv-check="'+i+'" '+((s.checks||[]).includes(i)?"checked":"")+'><span>'+esc(x)+'</span></label>').join("");
   h+='<div class="adv-academy-result" id="advTimer" aria-live="polite">Ready to submit. Your work will be checked after you submit.</div>';
   h+='<div class="adv-academy-result" id="advResult">'+(s.passed?"✓ Passed and saved on this device.":"Pass needs 10 seconds, at least 40 characters, 2 topic keywords, and all review checks.")+'</div>';
  }
  document.getElementById("advContent").innerHTML=h;
  if(current.page===2&&current.track==="Programming"){mountCodeWorkspace(l);}
  document.getElementById("advBack").disabled=current.page===0;
  const nextButton=document.getElementById("advNext");
  nextButton.textContent=current.page===3?"Submit for Review":"Next page →";
  if(current.page===3){
   nextButton.disabled=false;
  }else{
   if(reviewTimer){clearInterval(reviewTimer);reviewTimer=null;}
   reviewStartedAt=0;
   nextButton.disabled=false;
  }
  const all=load();all[id]={...all[id],lastPage:Math.max(all[id]?.lastPage||0,current.page)};save(all);
 }
 async function hydrateCloudProgress(){
  try{
   const client=window.rangersSupabase;
   let nextScope="guest";
   if(client){const auth=await client.auth.getUser();if(auth.data?.user?.id)nextScope=auth.data.user.id;}
   const scopeChanged=accountScope!==nextScope;
   accountScope=nextScope;
   if(scopeChanged){render(cadHost,cad,"CAD");render(progHost,prog,"Programming");if(modal.classList.contains("open")){notesText.value="";loadLessonNote();}}
   if(accountScope==="guest"||typeof window.rangersLoadCloudProgress!=="function")return;
   const remote=await window.rangersLoadCloudProgress();
   if(remote.error)throw remote.error;
   const all=load(),remoteKeys=new Set();
   (remote.data||[]).forEach(row=>{
    const academyName=String(row.academy||"").toLowerCase();
    const track=academyName==="cad"?"CAD":academyName==="programming"?"Programming":null;
    if(!track)return;
    const lessonId=String(row.lesson_id||"");
    const prefix=track+"-";
    if(!lessonId.startsWith(prefix))return;
    const index=Number(lessonId.slice(prefix.length));
    if(!Number.isInteger(index)||index<0)return;
    const id=track+"-"+index;
    remoteKeys.add(id);
    if(!all[id]?.passed)all[id]={...(all[id]||{}),passed:true,syncedFromCloud:true};
   });
   save(all);
   for(const [id,state] of Object.entries(all)){
    if(!state?.passed||remoteKeys.has(id))continue;
    const split=id.lastIndexOf("-");
    const track=id.slice(0,split);
    if(!["CAD","Programming"].includes(track))continue;
    const result=await window.rangersCloudSyncProgress(track.toLowerCase(),id,true);
    if(result?.error)console.warn("Could not upload saved Academy progress:",result.error.message);
   }
   render(cadHost,cad,"CAD");render(progHost,prog,"Programming");
  }catch(error){console.warn("Academy cloud progress could not be loaded:",error.message||error);}
 }
 function render(host,list,track){
  host.innerHTML='<div class="adv-academy-grid">'+list.map((l,i)=>{const s=load()[track+"-"+i]||{};return '<article class="adv-academy-card"><div class="academy-lesson-meta"><span>'+(track==="CAD"?"CAD":"PROGRAMMING")+'</span><span>'+(s.passed?"✓ PASSED":(track==="CAD"?"4 PAGES":"3 PAGES"))+'</span></div><h3>'+String(i+1).padStart(2,"0")+' · '+esc(l.title)+'</h3><p>'+esc(l.body)+'</p><button class="btn btn-primary btn-small" data-adv-open="'+track+':'+i+'">'+(s.passed?"Review lesson":"Open lesson")+'</button></article>'}).join("")+'</div>';
  host.querySelectorAll("[data-adv-open]").forEach(b=>b.addEventListener("click",()=>{const a=b.dataset.advOpen.split(":");current={track:a[0],index:Number(a[1]),page:0};reviewStartedAt=0;if(reviewTimer){clearInterval(reviewTimer);reviewTimer=null;}notesPanel.hidden=true;notesToggle.setAttribute("aria-expanded","false");modal.classList.add("open");notesDock.hidden=false;draw()}));
 }
 async function submit(){
  const submitButton=document.getElementById("advNext");
  if(submitButton.disabled)return;
  submitButton.disabled=true;
  const originalLabel=submitButton.textContent;
  submitButton.innerHTML='<span class="adv-review-spinner"></span> Checking your work…';
  const timer=document.getElementById("advTimer");
  if(timer)timer.innerHTML='<span class="adv-review-spinner"></span> Compiling evidence and checking your submission…';
  const started=Date.now();
  await new Promise(resolve=>setTimeout(resolve,10000));
  const d=data(),l=lesson(),e=document.getElementById("advEvidence").value.trim();
  const checks=[...document.querySelectorAll("[data-adv-check]")].filter(x=>x.checked).map(x=>Number(x.dataset.advCheck));
  const matched=matchedReviewKeywords(l,e),required=Math.min(2,reviewKeywords(l).length);
  const waited=Date.now()-started>=10000;
  const enoughText=e.length>=40,hasKeywords=matched.length>=required,allChecks=checks.length===d.checks.length;
  const passed=waited&&enoughText&&hasKeywords&&allChecks,id=current.track+"-"+current.index,all=load();
  all[id]={...(all[id]||{}),lastPage:3,evidence:e,checks,passed,matchedKeywords:matched,submittedAt:new Date().toISOString()};save(all);
   let cloudSyncMessage="";
   if(passed&&typeof window.rangersCloudSyncProgress==="function"){
    const synced=await window.rangersCloudSyncProgress(current.track.toLowerCase(),id,true);
    cloudSyncMessage=synced?.error?" Cloud sync failed: "+synced.error.message:" Progress synced to your Rangers account.";
   }
  const result=document.getElementById("advResult");
  if(passed)result.textContent="✓ Passed! Your evidence includes relevant topic keywords and all review checks. Progress is saved on this device."+cloudSyncMessage;
  else{
   const issues=[];
   if(!waited)issues.push("complete the review check");
   if(!enoughText)issues.push("write at least 40 characters about your actual work");
   if(!hasKeywords)issues.push("include at least "+required+" topic keywords (matched: "+(matched.join(", ")||"none")+")");
   if(!allChecks)issues.push("check all "+d.checks.length+" review criteria");
   result.textContent="Not passed yet: "+issues.join("; ")+".";
  }
  submitButton.textContent=originalLabel;submitButton.disabled=false;
  if(timer)timer.textContent="✓ Review complete. "+(passed?"Your work passed the review.":"Review finished — see the feedback above.");
  if(passed){const xp=JSON.parse(localStorage.getItem(xpKey())||"{}");const award="advanced-v2-"+id;if(!xp[award]){xp[award]=60;localStorage.setItem(xpKey(),JSON.stringify(xp));}}
  render(cadHost,cad,"CAD");render(progHost,prog,"Programming");
 }
 document.getElementById("advClose").addEventListener("click",()=>{modal.classList.remove("open");notesDock.hidden=true;notesPanel.hidden=true;notesToggle.setAttribute("aria-expanded","false")});modal.addEventListener("click",e=>{if(e.target===modal){modal.classList.remove("open");notesDock.hidden=true;notesPanel.hidden=true;notesToggle.setAttribute("aria-expanded","false")}});
